// Extract task from webhook payload
const task = $input.item.json.body.task;
const context = $input.item.json.body.context || {};
const userId = $input.item.json.body.userId;
const conversationId = $input.item.json.body.conversationId;

// Validate HMAC signature
const crypto = require('crypto');
const receivedSignature = $input.item.json.headers['x-webhook-secret'];
const webhookSecret = $env.N8N_WEBHOOK_SECRET;
const payload = JSON.stringify($input.item.json.body);
const expectedSignature = crypto.createHmac('sha256', webhookSecret).update(payload).digest('hex');

if (receivedSignature !== expectedSignature) {
  throw new Error('Invalid webhook signature');
}

// Decompose task into subtasks using AI
const subtasks = [];

// Pattern detection for task type
if (task.match(/create|build|generate/i)) {
  subtasks.push({
    type: 'research',
    description: `Research requirements for: ${task}`,
    agent: 'research_agent',
    priority: 1
  });
  subtasks.push({
    type: 'plan',
    description: `Create execution plan for: ${task}`,
    agent: 'planning_agent',
    priority: 2,
    dependsOn: ['research']
  });
  subtasks.push({
    type: 'build',
    description: `Execute build for: ${task}`,
    agent: 'build_agent',
    priority: 3,
    dependsOn: ['plan']
  });
  subtasks.push({
    type: 'validate',
    description: `Validate output for: ${task}`,
    agent: 'validation_agent',
    priority: 4,
    dependsOn: ['build']
  });
} else if (task.match(/fix|debug|repair/i)) {
  subtasks.push({
    type: 'analyze',
    description: `Analyze error: ${task}`,
    agent: 'error_analysis_agent',
    priority: 1
  });
  subtasks.push({
    type: 'fix',
    description: `Generate fix for: ${task}`,
    agent: 'autofix_agent',
    priority: 2,
    dependsOn: ['analyze']
  });
  subtasks.push({
    type: 'test',
    description: `Test fix for: ${task}`,
    agent: 'testing_agent',
    priority: 3,
    dependsOn: ['fix']
  });
} else if (task.match(/analyze|research|investigate/i)) {
  subtasks.push({
    type: 'gather',
    description: `Gather data for: ${task}`,
    agent: 'data_gathering_agent',
    priority: 1
  });
  subtasks.push({
    type: 'analyze',
    description: `Analyze data for: ${task}`,
    agent: 'analysis_agent',
    priority: 2,
    dependsOn: ['gather']
  });
  subtasks.push({
    type: 'summarize',
    description: `Summarize findings for: ${task}`,
    agent: 'summary_agent',
    priority: 3,
    dependsOn: ['analyze']
  });
} else {
  // Default decomposition
  subtasks.push({
    type: 'execute',
    description: task,
    agent: 'general_agent',
    priority: 1
  });
}

return {
  task,
  context,
  userId,
  conversationId,
  subtasks,
  totalSubtasks: subtasks.length,
  timestamp: new Date().toISOString()
};

// Get current subtask
const subtask = $input.item.json.subtasks[$input.context.nodesExecuted.splitSubtasks - 1];
const allSubtasks = $input.item.json.subtasks;
const completedResults = $input.context.completedResults || [];

// Check dependencies
if (subtask.dependsOn && subtask.dependsOn.length > 0) {
  const missingDeps = subtask.dependsOn.filter(dep => {
    return !completedResults.some(r => r.type === dep);
  });

  if (missingDeps.length > 0) {
    throw new Error(`Missing dependencies: ${missingDeps.join(', ')}`);
  }
}

// Route to appropriate agent based on type
const agentEndpoints = {
  research_agent: process.env.MUNDO_TANGO_URL + '/api/mrblue/research',
  planning_agent: process.env.MUNDO_TANGO_URL + '/api/mrblue/plan',
  build_agent: process.env.MUNDO_TANGO_URL + '/api/mrblue/build',
  validation_agent: process.env.MUNDO_TANGO_URL + '/api/mrblue/validate',
  error_analysis_agent: process.env.MUNDO_TANGO_URL + '/api/mrblue/analyze-error',
  autofix_agent: process.env.MUNDO_TANGO_URL + '/api/mrblue/autofix',
  testing_agent: process.env.MUNDO_TANGO_URL + '/api/mrblue/test',
  data_gathering_agent: process.env.MUNDO_TANGO_URL + '/api/mrblue/gather',
  analysis_agent: process.env.MUNDO_TANGO_URL + '/api/mrblue/analyze',
  summary_agent: process.env.MUNDO_TANGO_URL + '/api/mrblue/summarize',
  general_agent: process.env.MUNDO_TANGO_URL + '/api/mrblue/chat'
};

return {
  subtask,
  endpoint: agentEndpoints[subtask.agent] || agentEndpoints.general_agent,
  context: $input.item.json.context,
  userId: $input.item.json.userId,
  conversationId: $input.item.json.conversationId,
  previousResults: completedResults
};

// Store result in context
const result = {
  type: $input.item.json.subtask.type,
  agent: $input.item.json.subtask.agent,
  description: $input.item.json.subtask.description,
  output: $input.item.json.response,
  timestamp: new Date().toISOString(),
  success: true
};

// Get existing results from context
const completedResults = $input.context.completedResults || [];
completedResults.push(result);

// Update context
$input.context.completedResults = completedResults;

return {
  result,
  completedCount: completedResults.length,
  totalSubtasks: $input.item.json.totalSubtasks
};

// Aggregate all results
const completedResults = $input.context.completedResults || [];
const task = $input.item.json.task;
const userId = $input.item.json.userId;
const conversationId = $input.item.json.conversationId;

// Calculate success rate
const successCount = completedResults.filter(r => r.success).length;
const successRate = (successCount / completedResults.length) * 100;

// Generate summary using AI (call Groq)
const summaryPrompt = `Summarize the following multi-agent task execution:

Original Task: ${task}

Subtask Results:
${completedResults.map((r, i) => `${i + 1}. ${r.description}
   Agent: ${r.agent}
   Output: ${JSON.stringify(r.output).substring(0, 200)}...`).join('

')}

Provide a concise summary of what was accomplished and any key findings.`;

return {
  task,
  userId,
  conversationId,
  results: completedResults,
  summary: {
    totalSubtasks: completedResults.length,
    successCount,
    successRate: `${successRate.toFixed(1)}%`,
    duration: new Date() - new Date(completedResults[0].timestamp),
    summaryPrompt
  },
  timestamp: new Date().toISOString()
};

